  'dash.models.how_it_works_body': 'Ava еженедельно запускает вручную отобранный набор реальных задач программирования против каждой поддерживаемой модели. Каждый балл ссылается на точный промпт и точный ответ — откройте публичный репозиторий, чтобы прочитать любой транскрипт, предложить более строгую шкалу оценки или воспроизвести балл на вашей машине одной командой. Никакие пользовательские данные никогда не попадают в этот репозиторий.',
