  'dash.settings.autonomous_confirm': 'Переключиться в автономный режим?\n\nЭто автоматически одобряет все категории инструментов — bash, git, file_write, file_edit, database_query, browser, http_request — включая их деструктивное подмножество (rm, format, deletes, overwrites). Единственные операции, которые всё ещё запрашивают подтверждение — это необратимые действия (force-push, hard reset, history rewrites, package publish, git_commit --amend) — они никогда не становятся автоматическими.\n\nВыберите это только если вы хотите, чтобы Ava работала без подтверждений в течение долгих сессий, и только в рабочем пространстве, где можно восстановить ошибку записи через git.',
