  'dash.settings.custom_model': 'Пользовательская модель',
  'dash.settings.custom_model_desc': 'Укажите Ava любую модель — локальную (Ollama, LM Studio, vLLM на вашем компьютере) или удалённую (приватный кластер vLLM, самохостинг с дообучением, OpenRouter, Together, любой сервис, поддерживающий API OpenAI Chat Completions). Локальные серверы остаются на вашем компьютере; удалённые точки доступа получают безопасность, которую предоставляет ваш endpoint. Перезапустите панель чата после сохранения, чтобы изменения вступили в силу.',
